"""Rewrite tests/ from float money to Money (MIGRATION.md + AMENDMENTS)."""
import pathlib
import re
from decimal import Decimal, ROUND_HALF_UP, ROUND_HALF_EVEN, ROUND_DOWN

ROOT = pathlib.Path("/private/var/folders/w_/swqg2n117dzdrptxy6074cqw0000gp/T/w/59033f0a1600")

MODE = {
    "invoices": ROUND_HALF_UP,
    "billing": ROUND_HALF_UP,
    "tax": ROUND_HALF_UP,
    "fx": ROUND_HALF_EVEN,
    "interest": ROUND_HALF_EVEN,
    "refunds": ROUND_DOWN,
    "payouts": ROUND_HALF_EVEN,  # AMENDMENTS/001
    "reports": ROUND_HALF_UP,
    "export": ROUND_HALF_UP,
}

MINOR = {"USD": 2, "EUR": 2, "GBP": 2, "CHF": 2, "JPY": 0, "KWD": 3}

RATES = {}
for line in (ROOT / "ledgerly/_gen/rates_table.py").read_text().splitlines():
    m = re.match(r"\s+\('(\w+)', '(\w+)'\): Decimal\('([\d.]+)'\),", line)
    if m:
        RATES[(m.group(1), m.group(2))] = Decimal(m.group(3))


def money(amount, currency="USD"):
    return "Money(Decimal('%s'), '%s')" % (fmt(amount), currency)


def fmt(d):
    s = str(d)
    if "." in s:
        s = s.rstrip("0").rstrip(".")
    return s


def rnd(amount, currency, mode):
    exp = Decimal(1).scaleb(-MINOR[currency])
    return amount.quantize(exp, rounding=mode)


def split_top(s):
    """Split a call argument list on top-level commas."""
    out, depth, cur, quote = [], 0, "", None
    for ch in s:
        if quote:
            cur += ch
            if ch == quote:
                quote = None
            continue
        if ch in "'\"":
            quote = ch
            cur += ch
        elif ch in "([{":
            depth += 1
            cur += ch
        elif ch in ")]}":
            depth -= 1
            cur += ch
        elif ch == "," and depth == 0:
            out.append(cur.strip())
            cur = ""
        else:
            cur += ch
    if cur.strip():
        out.append(cur.strip())
    return out


def literal(s):
    """A python numeric literal as Decimal."""
    return Decimal(s)


def money_args(args, currency="USD"):
    return ", ".join(money(literal(a), currency) for a in args)


def transform_call(func, args, mode, pkg):
    """Return (new_call_text, new_expected_text)."""
    a = split_top(args)
    if func.endswith("_due_date") or func.startswith("normalize_"):
        return None, None
    if func == "convert_float":
        return None, None
    if func == "invoice_json":
        lines = re.match(r"\[\((.*?)\), \((.*?)\)\]", a[0])
        pairs = re.findall(r"\('([^']+)', ([\d.]+)\)", a[0])
        body = ", ".join("('%s', %s)" % (s, money(literal(v), a[1])) for s, v in pairs)
        total = rnd(sum(literal(v) for _, v in pairs), a[1], mode)
        doc = ('{"currency":"%s","lines":[%s],"total":{"amount":"%s","currency":"%s"}}'
               % (a[1],
                  ",".join('{"sku":"%s","amount":{"amount":"%s","currency":"%s"}}'
                           % (s, fmt(rnd(literal(v), a[1], mode)), a[1]) for s, v in pairs),
                  fmt(total), a[1]))
        return "invoice_json([%s], '%s')" % (body, a[1]), "'%s'" % doc
    if func == "ledger_csv":
        rows = re.findall(r"\('([^']+)', '([^']+)', ([\d.]+)\)", a[0])
        body = ", ".join("('%s', '%s', %s)" % (d, m, money(literal(v), a[1]))
                         for d, m, v in rows)
        return "ledger_csv([%s], '%s')" % (body, a[1]), None

    if func.endswith("_settled") or func.endswith("_exceeds"):
        return "%s(%s)" % (func, money_args(a)), "True"
    if func.startswith("format_"):
        return "%s(%s, '%s')" % (func, money(literal(a[0]), a[1]), a[1]), None
    if func.startswith("percent_of_"):
        amt, pct, cur = literal(a[0]), literal(a[1]), a[2]
        val = rnd(amt * pct / 100, cur, mode)
        return "%s(%s, Decimal('%s'), '%s')" % (func, money(amt, cur), fmt(pct), cur), money(val, cur)
    if func.startswith("net_"):
        amt, pct, cur = literal(a[0]), literal(a[1]), a[2]
        val = amt - rnd(amt * pct / 100, cur, mode)
        return "%s(%s, Decimal('%s'), '%s')" % (func, money(amt, cur), fmt(pct), cur), money(val, cur)
    if func.startswith("scaled_"):
        amt, f, cur = literal(a[0]), literal(a[1]), a[2]
        val = rnd(amt * f, cur, mode)
        return "%s(%s, Decimal('%s'), '%s')" % (func, money(amt, cur), fmt(f), cur), money(val, cur)
    if func.startswith("capped_"):
        amt, pct, cap, cur = literal(a[0]), literal(a[1]), literal(a[2]), a[3]
        val = min(rnd(amt * pct / 100, cur, mode), rnd(cap, cur, ROUND_HALF_EVEN))
        return ("%s(%s, Decimal('%s'), %s, '%s')"
                % (func, money(amt, cur), fmt(pct), money(cap, cur), cur)), money(val, cur)
    if func.startswith("accrued_"):
        bal, rate, days, cur = literal(a[0]), literal(a[1]), a[2], a[3]
        val = rnd(bal * rate / 100 * literal(days) / 365, cur, mode)
        return ("%s(%s, Decimal('%s'), %s, '%s')"
                % (func, money(bal, cur), fmt(rate), days, cur)), money(val, cur)
    if func.startswith("total_"):
        items = [literal(x) for x in re.findall(r"[\d.]+", a[0])]
        cur = a[1]
        val = rnd(sum(items), cur, mode)
        return ("%s([%s], '%s')"
                % (func, ", ".join(money(i, cur) for i in items), cur)), money(val, cur)
    if func.startswith("split_"):
        amt, parts, cur = literal(a[0]), int(a[1]), a[2]
        share = rnd(amt / parts, cur, mode)
        last = rnd(amt - share * (parts - 1), cur, mode)
        vals = [share] * (parts - 1) + [last]
        return ("%s(%s, %d, '%s')" % (func, money(amt, cur), parts, cur),
                "[%s]" % ", ".join(money(v, cur) for v in vals))
    if func.startswith("convert_"):
        amt, src, dst = literal(a[0]), a[1], a[2]
        val = rnd(amt * RATES[(src, dst)], dst, mode)
        return ("%s(%s, '%s', '%s')" % (func, money(amt, src), src, dst),
                money(val, dst))
    if func.startswith("quote_"):
        amt, src, dst, bp = literal(a[0]), a[1], a[2], a[3]
        val = rnd(amt * RATES[(src, dst)] * (1 - Decimal(bp) / 10000), dst, mode)
        return ("%s(%s, '%s', '%s', %s)" % (func, money(amt, src), src, dst, bp),
                money(val, dst))
    raise SystemExit("unhandled %s(%s)" % (func, args))


def pkg_of(path):
    m = re.match(r"test_(\w+?)_", path.name)
    return m.group(1)


def main():
    for path in sorted((ROOT / "tests").glob("test_*.py")):
        pkg = pkg_of(path)
        if path.name == "test_rates.py":
            text = path.read_text()
            text = text.replace("import unittest\n",
                                "import unittest\nfrom decimal import Decimal\n")
            text = text.replace("RATES[(\"USD\", \"EUR\")], 0.9213)",
                                "RATES[(\"USD\", \"EUR\")], Decimal(\"0.92130\")")
            path.write_text(text)
            print("rewrote", path.name)
            continue
        mode = MODE[pkg]
        text = path.read_text()
        out = []
        for line in text.split("\n"):
            m = re.match(r"^(\s*)self\.assertEqual\((.*)\)$", line)
            if not m:
                out.append(line)
                continue
            indent, inner = m.group(1), m.group(2)
            call, expected = split_top(inner)[0], split_top(inner)[1]
            fm = re.match(r"^(\w+)\((.*)\)$", call)
            new_call, new_expected = transform_call(fm.group(1), fm.group(2), mode, pkg)
            if new_call is None:
                out.append(line)
            else:
                out.append("%sself.assertEqual(%s, %s)" % (indent, new_call,
                                                           new_expected or expected))
        text = "\n".join(out)
        if "Money(" in text and "from ledgerly.money import Money" not in text:
            text = insert_import(text, "from ledgerly.money import Money")
        if "Decimal('" in text and "from decimal import Decimal" not in text:
            text = text.replace("import unittest\n", "import unittest\nfrom decimal import Decimal\n")
        path.write_text(text)
        print("rewrote", path.name)


def insert_import(text, line):
    lines = text.split("\n")
    idx = next(i for i, l in enumerate(lines) if l.startswith("from ledgerly."))
    if lines[idx].rstrip().endswith("("):
        end = idx
        while lines[end].strip() != ")":
            end += 1
        lines.insert(end + 1, line)
    else:
        lines.insert(idx + 1, line)
    return "\n".join(lines)


if __name__ == "__main__":
    main()

