    if lines[idx].rstrip().endswith("("):
        end = idx
        while lines[end].strip() != ")":
            end += 1
    else:
        end = idx
    existing = lines[idx].split()[1]
    if module < existing:
        lines.insert(idx, line)
    else:
        lines.insert(end + 1, line)
    return "\n".join(lines)


