            call, expected = parts[0], m.group(2)[len(parts[0]) + 2:]
            fm = re.match(r"^(\w+)\((.*)\)$", call)
            new_call, new_expected = transform_call(fm.group(1), fm.group(2), mode)
            if new_call is None:
                out.append(line)
            else:
                out.append("%sself.assertEqual(%s, %s)"
                           % (m.group(1), new_call, new_expected or expected))
        text = "\n".join(out)
        if "Money(" in text and "from ledgerly.money import Money" not in text:
            text = insert_import(text, "from ledgerly.money import Money", "ledgerly.money")
        if "Decimal('" in text and "from decimal import Decimal" not in text:
            text = text.replace("import unittest\n", "import unittest\nfrom decimal import Decimal\n")
        path.write_text(text)
